func Run(ctx context.Context, db *sql.DB, w io.Writer) error {
	rows, _ := db.QueryContext(ctx, "SELECT * FROM events")
	var all []Event
	for rows.Next() { var e Event; rows.Scan(&e.ID,&e.Payload,&e.TS); all = append(all, e) }
	sort.Slice(all, func(i,j int) bool { return all[i].TS.Before(all[j].TS) })
	return json.NewEncoder(w).Encode(all)
}
